fn run_pnpm(root: &Path, args: &[&str]) -> std::process::Output {
    let output = Command::new("pnpm").args(args).current_dir(root).output().unwrap();
    assert!(
        output.status.success(),
        "pnpm {args:?} failed: stdout={} stderr={}",
