        for (suffix, expected) in [
            ("", Coverage::Covers),
            ("*", Coverage::Covers),
            ("^", Coverage::Covers),
            ("~", Coverage::Covers),
            ("../lib", Coverage::Covers),
            ("@scope/lib@^", Coverage::Covers),
            ("^0.2.3", Coverage::DoesNotCover),
            ("@scope/lib@~0.2.3", Coverage::DoesNotCover),
            ("0.2.3", Coverage::DoesNotCover),
            (">=0.2.3", Coverage::Covers),
