    fn round_trip_exact_operator_range_rewrites_to_target_version() {
        let spec = make_npm_spec("=1.0.0");
        let target = npm_version("1.2.3");
        assert_eq!(raw_of(round_trip(&spec, &target)).as_deref(), Some("=1.2.3"));
