            diagnostic["code"] == "unknown-package"
                && diagnostic["message"]
                    .as_str()
                    .is_some_and(|message| message.contains("admitted npm workspace member"))
        }),
        "relative reference incorrectly resolved by package name: {status}"
    );
}

